// this is a good idea but npm passes the command line options to mocha - simply appends them to the script
// consider running mocha tests from here. Then we could even add a test manifest, report failures etc.
const fs = require('fs')
const path = require('path')
const yargs = require('yargs')

const npmConfig = {
  host: process.env.npm_config_host,
  port: process.env.npm_config_port,
  ns: process.env.npm_config_ns,
  pwd: process.env.npm_config_pwd,
  user: process.env.npm_config_user,
  logfile: process.env.npm_config_logfile,
}

const npmArgChangeRequested = npmConfig.host 
                           || npmConfig.port 
                           || npmConfig.ns
                           || npmConfig.pwd
                           || npmConfig.user
                           || npmConfig.logfile
                           || yargs.argv.host
                           || yargs.argv.pwd
                           || yargs.argv.ns
                           || yargs.argv.user
                           || yargs.argv.port
                           || yargs.argv.logfile

const argv = require('yargs')
            .default('user', '_SYSTEM')
            .default('pwd', 'SYS')
            .default('host', '127.0.0.1')
            .default('port', 1972)
            .default('ns', 'USER')
            .default('logfile', undefined)
            .argv

const config = {
  host: npmConfig.host? npmConfig.host : argv.host,
  port: npmConfig.port? parseInt(npmConfig.port) :argv.port,
  ns: npmConfig.ns? npmConfig.ns :argv.ns,
  user: npmConfig.user? npmConfig.user :argv.user,
  pwd: npmConfig.pwd? npmConfig.pwd :argv.pwd,
  logfile: npmConfig.logfile? npmConfig.logfile :argv.logfile
}

const filepath = path.join(__dirname, 'connection.config')

if (npmArgChangeRequested || !fs.existsSync(filepath)) {
  fs.writeFile(filepath, JSON.stringify(config), 'utf8', (err) => {
    if (err) {
      console.log('An error occurred while attempting to refresh test configuration')
      return console.log(err)
    } else {
      console.log(config)
    }
  })
}